import { formatExportValue, isExportUrl } from './exportFormat';
import { saveBlobAsFile } from './downloadFile';

const normalizeRow = (row) => {
  const normalized = {};
  Object.entries(row).forEach(([key, value]) => {
    normalized[key] = formatExportValue(value);
  });
  return normalized;
};

const applyUrlHyperlinks = (worksheet) => {
  worksheet.eachRow((row, rowNumber) => {
    if (rowNumber === 1) return;
    row.eachCell((cell) => {
      const raw = cell.value;
      const text = typeof raw === 'string' ? raw.trim() : '';
      if (!isExportUrl(text)) return;
      cell.value = { text, hyperlink: text };
      cell.font = { color: { argb: 'FF4CC66E' }, underline: true };
    });
  });
};

export const exportToExcel = async (data, filename, sheetName = 'Sheet1') => {
  if (!data || !data.length) {
    return;
  }

  const excelModule = await import('exceljs');
  const ExcelJS = excelModule.default ?? excelModule;

  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet(sheetName);

  const headers = Object.keys(data[0]);

  worksheet.columns = headers.map((header) => ({
    header,
    key: header,
    width: /url|image|video|audio|thumbnail|avatar|media/i.test(header)
      ? 48
      : Math.max(header.length + 5, 15),
  }));

  worksheet.getRow(1).font = { bold: true };
  worksheet.getRow(1).fill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FF4CC66E' },
  };
  worksheet.getRow(1).alignment = { vertical: 'middle', horizontal: 'center' };

  data.forEach((row) => {
    worksheet.addRow(normalizeRow(row));
  });

  applyUrlHyperlinks(worksheet);

  const buffer = await workbook.xlsx.writeBuffer();
  const blob = new Blob([buffer], {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  });
  saveBlobAsFile(blob, `${filename || 'export'}.xlsx`);
};
